mapper.select:
SELECT NO, ID, PASSWORD, NAME, SPECIALTY, LOCATION, WORK_TIME
FROM DOCTOR
WHERE ID = #{id} AND PASSWORD = #{password}

mapper.update:
UPDATE DOCTOR SET password = #{password}, name = #{name},
specialty=#{specialty}, location=#{location}, WORK_TIME = #{workTime}
where no = #{no}

UPDATE DOCTOR
SET ENABLED = 0
WHERE NO = #{no}
